    public static CharSequence message(String value) { return message(value, 0, false); }
    private static CharSequence message(String value, int depth, boolean diagnosticOnly) {
        if (value == null) return "";
        if (depth >= 8) return value;
        int id = resource(value);
        if (id != 0 && (!diagnosticOnly || diagnostic(value))) return Language.msg(id);
        // ParlonsRemote.callOnce uses Future.get with a RuntimeException from onError.
        // Unwrap only recognized diagnostic descriptors; keep unfamiliar failures verbatim.
        String rpcPrefix = "java.lang.RuntimeException: ";
        if (value.startsWith(rpcPrefix)) {
            CharSequence nested = message(value.substring(rpcPrefix.length()), depth + 1, true);
            return nested instanceof Language.Message ? nested : value;
        }
        if (value.startsWith("resync refused: ")) {
            String tail = value.substring(16);
            return Language.msg(R.string.l10n_server_error_resync_refused, message(tail, depth + 1, true));
        }
        if (value.startsWith("node error: ")) {
            String tail = value.substring(12);
            return Language.msg(R.string.l10n_server_error_node_failure, message(tail, depth + 1, true));
        }
        if (value.startsWith("hosting failed: ")) {
            String tail = value.substring(16);
            return Language.msg(R.string.l10n_server_error_host_failure, message(tail, depth + 1, true));
        }
        if (value.startsWith("could not create the collection folder: ")) {
            String tail = value.substring(40);
            return Language.msg(R.string.l10n_server_error_collection_folder, message(tail, depth + 1, true));
        }
        if (value.startsWith("could not list: ")) {
            String tail = value.substring(16);
            return Language.msg(R.string.l10n_server_error_list_failure, message(tail, depth + 1, true));
        }
        if (value.startsWith("could not delete: ")) {
            String tail = value.substring(18);
            return Language.msg(R.string.l10n_server_error_delete_failure, message(tail, depth + 1, true));
        }
        if (value.startsWith("unknown contact ")) {
            String tail = value.substring(16);
            return Language.msg(R.string.l10n_ios_error_unknown_contact, tail);
        }
        if (value.startsWith("chunk unavailable: ")) {
            String tail = value.substring(19);
            return Language.msg(R.string.l10n_ios_error_chunk_unavailable, tail);
        }
        String[][] counters = {
            {"can only RAISE above the current ", "current"},
            {"above the key's maximum ", "maximum"}
        };
        for (int i = 0; i < counters.length; i++) if (value.startsWith(counters[i][0])) {
            String number = value.substring(counters[i][0].length());
            if (number.matches("[0-9]+")) return Language.msg(i == 0 ? R.string.l10n_server_error_counter_above_current : R.string.l10n_server_error_counter_above_maximum, number);
        }
        java.util.regex.Matcher group = GROUP_LIMIT.matcher(value);
        if (group.matches()) return Language.msg(R.string.l10n_server_error_group_limit, group.group(1), group.group(2));
        return value;
    }
    private static final java.util.regex.Pattern GROUP_LIMIT = java.util.regex.Pattern.compile("a group holds at most ([0-9]+) members [(]([0-9]+) asked[)]");
    public static String text(Context context, String value) {
        CharSequence message = message(value);
        return message instanceof Language.Message ? ((Language.Message) message).resolve(context) : message.toString();
    }
